// === Tab: mySketch ===
function setup() {
  createCanvas(600, 600);
  background(255);
  strokeWeight(1);
  noFill();

  let x = 200;
  let y = 250; 
  translate(width / 2, height / 2);

  for (let i = 0; i < x; i++) {
    let angle1 = TWO_PI * i / x;
    let x1 = cos(angle1) * y;
    let y1 = sin(angle1) * y;
    let j = (i * 2) % x;
    let angle2 = TWO_PI * j / x;
    let x2 = cos(angle2) * y;
    let y2 = sin(angle2) * y;

    stroke((i * 5) % 255, 100, 200, 150);
    line(x1, y1, x2, y2);
  }
}


